insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_pe_v1'
from (values
('116.28.b.1.A',3,'An eighth grader in a lifelong-fitness unit mixes jogging, side shuffles and high knees in one interval set. This shows...','["combining locomotor skills in a dynamic workout", "skipping the warm-up", "using only manipulative skills", "avoiding all footwork"]'::jsonb,0,'Locomotor skills can be blended for fitness.','original'),
('116.28.b.1.A',3,'Which workout chain uses only locomotor skills?','["grip, swing, release, follow", "gallop, hop, leap, sprint", "throw, bounce, strike, catch", "stretch, hold, breathe, relax"]'::jsonb,1,'Locomotor skills carry the body through space.','original'),
('116.28.b.1.B',3,'A volleyball player blocks at the net and lands. The safest combination of jump and landing technique is to...','["land on one stiff leg", "land on the heels with locked knees", "jump, extend upward and land softly on both feet with bent knees", "turn the back and fall"]'::jsonb,2,'Combining a controlled takeoff with a soft landing protects the joints.','original'),
('116.28.b.1.B',3,'After a long jump in track, the landing should...','["be flat with locked knees", "happen on the toes only", "be stiff-legged", "absorb the force with bent knees and hips"]'::jsonb,3,'Flexed joints absorb impact.','original'),
('116.28.b.2.A',3,'Combining balance with control in a skate or board sport requires...','["a low stance and eyes looking where you want to go", "standing upright and looking down", "tensing every muscle", "closing the eyes"]'::jsonb,0,'Posture and focus keep balance.','original'),
('116.28.b.2.A',3,'In gymnastics, a student improves static balance by...','["moving the arms wildly", "tightening the core and keeping a steady focus point", "looking away often", "holding the breath"]'::jsonb,1,'Core control and focus aid balance.','original'),
('116.28.b.2.B',3,'Proper body positioning for a ground stroke in tennis includes...','["backing away", "staying square with feet together", "turning sideways and stepping toward the ball", "standing on tiptoes"]'::jsonb,2,'Stepping into the ball improves power and control.','original'),
('116.28.b.2.B',3,'In an offensive set play, spacing means...','["ignoring the ball", "standing behind a defender", "bunching in one spot", "teammates positioning themselves to create open passing lanes"]'::jsonb,3,'Space opens options for the ball handler.','original'),
('116.28.b.3.A',3,'A quarterback combines throwing techniques by...','["stepping, rotating the trunk and following through to the receiver", "turning away from the target", "using only the wrist", "throwing flat-footed"]'::jsonb,0,'Combined body parts create accurate throws.','original'),
('116.28.b.3.A',3,'Throwing different distances in a game requires...','["throwing at the same speed every time", "adjusting the force and arm angle to the situation", "closing the eyes", "throwing only underhand"]'::jsonb,1,'Skilled throwers adapt.','original'),
('116.28.b.3.B',3,'To catch a pass thrown high and wide, a receiver should...','["wait without moving", "use a flat palm", "move to the ball and reach with soft hands", "turn away from it"]'::jsonb,2,'Moving into line improves the catch.','original'),
('116.28.b.3.B',3,'A catch at chest height is made best with...','["palms down", "closed fists", "pinkies together", "thumbs together and hands forming a diamond shape"]'::jsonb,3,'Hand shape matches the pass level.','original'),
('116.28.b.3.C',3,'To dribble without looking at the ball, a skilled player...','["uses finger pads and a feel for the ball while scanning the court", "slaps the ball with the palm", "stares at the ball", "carries the ball"]'::jsonb,0,'Without-cue control frees the eyes.','original'),
('116.28.b.3.C',3,'A player dribbling in traffic protects the ball by...','["turning the back to the basket and standing still", "using the body and the off-hand as a shield", "dribbling high", "holding it out in front"]'::jsonb,1,'Shielding keeps the ball safe.','original'),
('116.28.b.3.D',3,'In soccer, performing a push pass without cue requires...','["a loose ankle", "the toe poked hard", "the inside of the foot, a firm ankle and a follow-through toward the target", "the heel only"]'::jsonb,2,'Inside-of-foot control gives accuracy.','original'),
('116.28.b.3.D',3,'A foot-dribbling skill that helps shield the ball is...','["kicking it into the air", "standing still", "dribbling away from the goal", "keeping the body between the ball and the defender"]'::jsonb,3,'Shielding keeps possession.','original'),
('116.28.b.3.E',3,'To kick a ball with accuracy in a game, the kicker''s non-kicking foot should be...','["planted beside the ball pointing at the target", "behind the ball", "far to the side", "off the ground"]'::jsonb,0,'The plant foot sets direction.','original'),
('116.28.b.3.E',3,'Which kick lofts the ball the highest?','["light touches with the toe", "contact below the center of the ball with the instep", "contact with the side only", "contact above the center"]'::jsonb,1,'Hitting under the ball sends it upward.','original'),
('116.28.b.3.F',3,'An advanced volleyball hitter jumps and strikes the ball with...','["a flat foot", "a closed fist", "an open hand at the top of the reach", "a tucked arm"]'::jsonb,2,'Contact at full reach adds power.','original'),
('116.28.b.3.F',3,'To volley accurately during a game, a player without cue...','["closes the eyes", "walks away", "swats randomly", "positions under the ball and uses the same hand shape every time"]'::jsonb,3,'Consistency improves accuracy.','original'),
('116.28.b.3.G',3,'In badminton, a smash is hit...','["overhead with a fast downward swing", "with the racket behind the back", "underhand with no wrist", "from the floor"]'::jsonb,0,'A smash is a powerful overhead shot.','original'),
('116.28.b.3.G',3,'Skilled strikers keep the eyes on the object and...','["freeze the legs", "step toward the target and rotate the hips", "lean away", "swing with only the fingers"]'::jsonb,1,'Weight transfer and rotation create power.','original'),
('116.28.b.3.H',3,'A partner jump rope routine can include...','["standing apart without a rope", "avoiding eye contact and timing", "turning the rope for each other and jumping in sync", "walking only"]'::jsonb,2,'Partner routines build coordination and teamwork.','original'),
('116.28.b.3.H',3,'To perform a group jump rope routine well, the team should...','["start at different times", "ignore the rope turners", "jump randomly", "agree on the pattern and count the rhythm together"]'::jsonb,3,'Shared timing makes the group routine work.','original'),
('116.28.b.4.A',3,'A player who runs to a gap in the defense without being told is applying...','["open space on offense", "zone defense", "closed space", "a foul"]'::jsonb,0,'Reading the field and moving into space is a game skill.','original'),
('116.28.b.4.A',3,'A defender who cuts off the passing lane is...','["leaving the court", "closing space to limit the offense", "giving the offense more room", "ignoring the play"]'::jsonb,1,'Closing space shrinks options.','original'),
('116.28.b.4.B',3,'In field hockey, direction and force of a shot depend on...','["the color of the stick", "the weather only", "the angle of the stick face and the swing speed", "how loud the swing is"]'::jsonb,2,'Face angle and speed decide where and how hard the ball goes.','original'),
('116.28.b.4.B',3,'In lacrosse, a player cradles the ball by...','["throwing the stick", "holding the stick still", "dropping the stick", "rotating the wrists to keep it in the pocket"]'::jsonb,3,'Cradling keeps the ball secure.','original'),
('116.28.b.5',3,'A contra or square dance is a rhythmic activity that depends on...','["following patterns and timing with partners", "racing", "shooting", "blocking"]'::jsonb,0,'Folk dances use set patterns and rhythm.','original'),
('116.28.b.5',3,'Performing a dance routine in time with music means...','["ignoring the beat", "matching steps to the tempo and beat", "dancing faster than the music", "stopping randomly"]'::jsonb,1,'Staying on the beat is a rhythmic skill.','original'),
('116.28.b.6.A',3,'In a game of ultimate (invasion), a team keeps possession by...','["standing still", "holding the disc", "making short, safe passes and moving after each pass", "throwing to the defense"]'::jsonb,2,'Movement after passing keeps the offense alive.','original'),
('116.28.b.6.A',3,'In pickleball (net game), a strong defensive strategy is to...','["stand at the baseline with no movement", "hit it at the opponent''s feet only", "hit it into the net", "return the ball deep and move back to the ready position"]'::jsonb,3,'Position and placement matter.','original'),
('116.28.b.6.B',3,'Skilled players link skills without cue, such as...','["receiving a pass, pivoting and passing again", "stopping after each skill to think", "walking between plays", "waiting for the teacher"]'::jsonb,0,'Fluid sequences show mastery.','original'),
('116.28.b.6.B',3,'A sequence to score in team handball might be...','["pass to the other team", "dribble, pass, move to open space and shoot", "walk off the court", "shoot, then sit"]'::jsonb,1,'Combining skills achieves team goals.','original'),
('116.28.b.6.C',3,'Self-officiating in a game means...','["only a referee decides", "the winning team calls everything", "players call their own fouls honestly and settle disputes fairly", "players ignore the rules"]'::jsonb,2,'Honesty drives self-officiating.','original'),
('116.28.b.6.C',3,'Respect for opponents and officials is shown by...','["mocking officials", "arguing every call", "ignoring the rules", "following rules and accepting decisions"]'::jsonb,3,'Sporting behavior builds trust.','original'),
('116.28.b.7',3,'Rock climbing safety includes...','["using a harness, a belay partner and checking knots", "skipping helmets", "climbing alone without gear", "ignoring knots"]'::jsonb,0,'Safety checks prevent accidents.','original'),
('116.28.b.7',3,'Outdoor recreation planning includes checking...','["nothing", "the weather, trail conditions and emergency supplies", "only the clock", "only the snack"]'::jsonb,1,'Prepared people stay safe.','original'),
('116.28.b.8.A',3,'Performing lifelong activities such as walking, swimming and cycling can...','["end all stress for good", "stop all aging", "improve cardiorespiratory health over a lifetime", "replace sleep"]'::jsonb,2,'These activities are sustainable throughout life.','original'),
('116.28.b.8.A',3,'A lifelong activity that builds flexibility is...','["reading", "video gaming", "napping", "yoga"]'::jsonb,3,'Yoga stretches and strengthens muscles.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g8_pe_v1'
from (values
('116.28.b.8.B',3,'Performing the FITT principle in a running plan could mean...','["running 3 days a week for 20 minutes at a moderate pace", "sitting still", "running once a year", "using no schedule"]'::jsonb,0,'FITT sets how often, how hard, how long and what kind.','original'),
('116.28.b.8.B',3,'To increase intensity safely, a student can...','["skip warm-ups", "add a small amount of speed or resistance gradually", "ignore pain", "double the load at once"]'::jsonb,1,'Gradual overload reduces injury risk.','original'),
('116.28.b.8.C',3,'A student analyzes a personal fitness plan and finds that a low result on a push-up test shows weak...','["body fat", "reaction time", "muscular strength and endurance", "flexibility"]'::jsonb,2,'Push-ups test upper-body muscle.','original'),
('116.28.b.8.C',3,'A skill-related component that helps in sprinting from a start is...','["body composition", "flexibility", "muscular endurance", "speed"]'::jsonb,3,'Speed is how fast you can move.','original'),
('116.28.b.9.A',3,'To create and implement a personal fitness plan, a student first...','["sets goals and measures a starting point", "skips testing", "copies someone else''s", "avoids goals"]'::jsonb,0,'A baseline lets progress be measured.','original'),
('116.28.b.9.A',3,'After following a plan for six weeks, a student should...','["never test again", "retest and compare results to the starting point", "ignore changes", "throw away the plan"]'::jsonb,1,'Reassessing shows progress.','original'),
('116.28.b.9.B',3,'Evaluating a fitness goal means...','["declaring it perfect", "ignoring data", "checking whether progress matches the goal and revising if needed", "stopping all effort"]'::jsonb,2,'Adjust the plan using data.','original'),
('116.28.b.9.B',3,'If a student''s mile time has not improved after eight weeks, the best action is to...','["keep the same plan forever", "quit exercising", "blame the track", "change the training type, time or intensity"]'::jsonb,3,'Plans must adapt.','original'),
('116.28.b.10.A',3,'A food plan that enhances physical performance includes...','["balanced meals and snacks before and after activity", "only energy drinks", "only desserts", "skipping meals before a game"]'::jsonb,0,'Fuel timing helps performance.','original'),
('116.28.b.10.A',3,'Eating a meal rich in complex carbohydrates before a long event helps...','["dehydrate you", "provide steady energy", "cause immediate fatigue", "slow reaction time"]'::jsonb,1,'Complex carbs digest slowly.','original'),
('116.28.b.10.B',3,'Hydration needs go up when...','["reading", "sleeping", "exercise is long, intense or in hot weather", "resting in cool shade"]'::jsonb,2,'Sweat loss increases fluid needs.','original'),
('116.28.b.10.B',3,'A way to monitor hydration without cue is to check...','["hair length", "shoe size", "height", "the color of urine and thirst"]'::jsonb,3,'Pale urine suggests good hydration.','original'),
('116.28.b.11.A',3,'Without being reminded, a student chooses protective gear such as...','["a mouthguard and shin guards for contact sports", "only a cap", "flip-flops", "no gear"]'::jsonb,0,'Independent safety choices are a goal at this level.','original'),
('116.28.b.11.A',3,'A well-prepared athlete checks equipment...','["only once a year", "for damage and proper fit before each use", "never", "after an injury"]'::jsonb,1,'Pre-checks prevent equipment failure.','original'),
('116.28.b.11.B',3,'A pedestrian safety precaution is to...','["wear headphones loudly while crossing", "run across the street", "cross at crosswalks and watch for vehicles", "walk in traffic lanes"]'::jsonb,2,'Awareness keeps walkers safe.','original'),
('116.28.b.11.B',3,'A safe response when lightning is near an outdoor activity is to...','["swim", "stand under a lone tree", "keep playing", "move indoors immediately"]'::jsonb,3,'Lightning is dangerous outdoors.','original'),
('116.28.b.12.A',3,'Demonstrating respect for similarities and differences in teams means...','["valuing each teammate''s strengths", "separating by ability", "teasing differences", "ignoring skill levels"]'::jsonb,0,'Strength comes from variety.','original'),
('116.28.b.12.A',3,'A positive team culture is built when players...','["tease others", "support each other and include all classmates", "exclude newcomers", "blame others"]'::jsonb,1,'Inclusion builds trust.','original'),
('116.28.b.12.B',3,'Evaluating self-management after a loss, a strong response is to...','["blame the officials", "quit the team", "reflect on what to improve and stay positive", "refuse to practice"]'::jsonb,2,'Reflection builds resilience.','original'),
('116.28.b.12.B',3,'A sign of strong self-control during competition is...','["tossing the equipment", "yelling at the ref", "walking off", "staying calm and focused under pressure"]'::jsonb,3,'Self-control supports good decisions.','original'),
('116.28.b.13.A',3,'A socially acceptable way to resolve a conflict about a rule is to...','["discuss it respectfully and agree on a solution", "argue until someone quits", "insist on your way only", "ignore the issue"]'::jsonb,0,'Compromise settles disputes.','original'),
('116.28.b.13.A',3,'Resolving conflict without being told to do so shows...','["anger", "maturity and responsibility", "weakness", "boredom"]'::jsonb,1,'Taking initiative solves problems early.','original'),
('116.28.b.13.B',3,'A teammate who restates the other person''s concern before replying is using...','["blaming", "interrupting", "active listening", "avoiding"]'::jsonb,2,'Restating shows understanding.','original'),
('116.28.b.13.C',3,'Empathy toward an opponent who was injured is shown by...','["continuing to play", "cheering", "ignoring the injury", "stopping play and checking on them"]'::jsonb,3,'Care for others comes before the game.','original'),
('116.28.b.13.C',3,'Mutual respect among teammates includes...','["valuing each person''s effort and listening to ideas", "mocking weak skills", "ignoring suggestions", "choosing favorites only"]'::jsonb,0,'Respect makes teams stronger.','original'),
('116.28.b.14',3,'A student with perseverance, after missing the team in tryouts, might...','["blame the coach", "keep practicing and try again", "quit for good", "stop all activity"]'::jsonb,1,'Perseverance means bouncing back.','original'),
('116.28.b.14',3,'Which attitude shows perseverance?','["I''ll never get it", "I give up", "this is hard, but I will keep working", "it doesn''t matter"]'::jsonb,2,'Persistent effort builds mastery.','original'),
('116.28.b.15',3,'Providing constructive feedback to a teammate is best done...','["by laughing", "by shouting", "by pointing out every flaw", "privately or kindly, focusing on actions rather than the person"]'::jsonb,3,'Kind, specific feedback is easiest to hear.','original'),
('116.28.b.15',3,'A player who accepts feedback from a coach and applies it shows...','["growth mindset", "carelessness", "pride", "stubbornness"]'::jsonb,0,'Learning from feedback is a strength.','original'),
('116.28.b.16.A',3,'Implementing a plan using technology to be active could involve...','["watching a screen with no movement", "setting a heart rate goal on a watch and logging workouts", "ignoring data", "deleting the app"]'::jsonb,1,'Wearables help track effort.','original'),
('116.28.b.16.A',3,'Online workout videos can help a student plan activity by...','["discouraging effort", "replacing all movement", "providing guided routines at different levels", "being the only exercise"]'::jsonb,2,'Technology can support a plan.','original'),
('116.28.b.16.B',3,'Participating in self-selected activities for personal enjoyment helps students...','["get bored faster", "feel forced", "avoid all exercise", "stay active by choice"]'::jsonb,3,'Choice builds motivation.','original'),
('116.28.b.16.B',3,'An eighth grader who joins a hiking club on weekends is likely to...','["build a lifelong habit of enjoyable activity", "stop moving", "lose all interest", "avoid friends"]'::jsonb,0,'Enjoyment sustains activity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Physical Education' and d.language = 'en'
